import sys
sys.path.append('storage/quaero')
from utils import ResidualDSConvBlock, NetworkWrapper

import jax
import jax.numpy as jnp
import flax.linen as nn
import optax
from typing import Any, Dict, Sequence

# --- Standard Prediction Head Modules ---
class StandardRegressionHead(nn.Module):
    d_output: int; dense_dim: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        norm = jnp.linalg.norm(x, ord=2, axis=-1, keepdims=True)
        x = x / (norm + 1e-6)
        z = nn.Dense(self.dense_dim)(x); z = nn.gelu(z)
        z = nn.Dropout(rate=self.dropout_rate)(z, deterministic=deterministic)
        return nn.Dense(self.d_output)(z).squeeze(-1)

class GenericHead(nn.Module):
    d_output: int; dense_dim: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        z = nn.Dense(self.dense_dim)(x); z = nn.gelu(z)
        z = nn.Dropout(rate=self.dropout_rate)(z, deterministic=deterministic)
        return nn.Dense(self.d_output)(z)

# --- Novel Siamese Head for CRI-Off ---
class SiameseInteractionHead(nn.Module):
    d_output: int; dense_dim: int; dropout_rate: float
    @nn.compact
    def __call__(self, h, deterministic=True):
        seq_len = h.shape[1]
        # The CRI-Off sequence is 23-base sgRNA + 3-base PAM + 23-base target DNA.
        # We will approximate the split point. A more precise method might be needed.
        split_point = 26 

        h_sg = h[:, :split_point, :]
        h_tgt = h[:, split_point:, :]

        z_sg = jnp.concatenate([jnp.mean(h_sg, axis=1), jnp.max(h_sg, axis=1)], axis=-1)
        z_tgt = jnp.concatenate([jnp.mean(h_tgt, axis=1), jnp.max(h_tgt, axis=1)], axis=-1)

        z_sg_norm = z_sg / (jnp.linalg.norm(z_sg, ord=2, axis=-1, keepdims=True) + 1e-6)
        z_tgt_norm = z_tgt / (jnp.linalg.norm(z_tgt, ord=2, axis=-1, keepdims=True) + 1e-6)

        diff = z_sg_norm - z_tgt_norm
        prod = z_sg_norm * z_tgt_norm

        final_vec = jnp.concatenate([z_sg_norm, z_tgt_norm, diff, prod], axis=-1)

        z = nn.Dense(self.dense_dim)(final_vec); z = nn.gelu(z)
        z = nn.Dropout(rate=self.dropout_rate)(z, deterministic=deterministic)
        return nn.Dense(self.d_output)(z).squeeze(-1)

# --- Main Network ---
class QuaeroHybridHeadNetwork(nn.Module):
    d_output: int; task_type: str; d_model_common: int; ds_num_blocks: int
    ds_dilations: Sequence[int]; ds_kernel_size: int; motif_kernel_size: int
    dropout_rate: float; head_intermediate_dim: int; dataset_name: str

    @nn.compact
    def __call__(self, x, deterministic=True, **kwargs):
        x = nn.Dense(self.d_model_common)(x); x = nn.gelu(x)
        for i in range(self.ds_num_blocks):
            x = ResidualDSConvBlock(d_model=self.d_model_common, kernel_size=self.ds_kernel_size, dilation=(self.ds_dilations[i]), dropout_rate=self.dropout_rate)(x, deterministic=deterministic)
        cnn_features = x

        if self.dataset_name == 'CRI-Off':
            return SiameseInteractionHead(d_output=self.d_output, dense_dim=self.head_intermediate_dim, dropout_rate=self.dropout_rate)(cnn_features, deterministic=deterministic)

        main_path = jnp.concatenate([jnp.mean(cnn_features, axis=1), jnp.max(cnn_features, axis=1)], axis=-1)
        motif_f = nn.gelu(nn.Conv(self.d_model_common, (self.motif_kernel_size,), padding='SAME')(cnn_features))
        specialized_path = jnp.max(motif_f, axis=1)
        fused = jnp.concatenate([main_path, specialized_path], axis=-1)
        fused = nn.LayerNorm()(fused)
        fused = nn.Dropout(rate=self.dropout_rate)(fused, deterministic=deterministic)

        head_args = {'d_output': self.d_output, 'dense_dim': self.head_intermediate_dim, 'dropout_rate': self.dropout_rate}
        if self.task_type == "regression": return StandardRegressionHead(**head_args)(fused, deterministic=deterministic)
        else: return GenericHead(**head_args)(fused, deterministic=deterministic)

def _define_hyperparameters():
    return {
        'learning_rate': 0.001, 'd_model_common': 256, 'ds_num_blocks': 5,
        'ds_dilations': (1, 2, 4, 8, 16), 'ds_kernel_size': 7, 'motif_kernel_size': 5,
        'dropout_rate': 0.1, 'head_intermediate_dim': 128, 'weight_decay': 0.02,
    }

def create_network(hparams: Dict[str, Any]):
    network_params = {k: hparams.get(k) for k in _define_hyperparameters() if k not in ['learning_rate', 'weight_decay']}
    network_params.update({
        'd_output': hparams.get('d_output'), 
        'task_type': hparams.get('task_type'),
        'dataset_name': hparams.get('dataset') # Pass dataset name for conditional head
    })
    return NetworkWrapper(QuaeroHybridHeadNetwork(**network_params))

def create_optimizer(learning_rate: float = 0.001, weight_decay: float = 0.02):
    return optax.chain(optax.clip_by_global_norm(0.75), optax.adamw(learning_rate=learning_rate, weight_decay=weight_decay))
